const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfo(eeObj) {
    return new Promise((resolve, reject) => {
      eeObj.getInfo(resolve, reject);
    });
  }

  try {
    // 1. Geometry & Time Definitions
    const centralValley = ee.Geometry.Polygon([
      [-122.5, 40.8],
      [-121.5, 40.8],
      [-120.5, 39.8],
      [-119.5, 38.5],
      [-118.7, 36.7],
      [-118.9, 35.0],
      [-120.5, 35.0],
      [-121.5, 36.0],
      [-122.4, 37.5],
      [-122.6, 39.2],
      [-122.5, 40.8]
    ], null, false);
    const start = '2022-10-01';
    const end = '2023-03-31';
    const scaleMeters = 5000;
    const thresholdInches = 15;
    const thresholdMm = thresholdInches * 25.4;

    // 2. Data Acquisition & Check
    let dataset = 'CHIRPS';
    let col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(start, end)
      .filterBounds(centralValley);
    let nImages = await getInfo(col.size());

    if (nImages === 0) {
      // Fallback to ERA5-Land Daily Aggregated
      dataset = 'ERA5-LAND';
      col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
        .filterDate(start, end)
        .filterBounds(centralValley);
      nImages = await getInfo(col.size());
      if (nImages === 0) {
        console.log(`Images: CHIRPS=0, ERA5-LAND=0 (${start} to ${end})`);
        console.log('C1');
        return;
      }
    }

    // 3. Processing
    let sumMmImg;
    if (dataset === 'CHIRPS') {
      // CHIRPS precipitation in mm/day
      sumMmImg = col.select('precipitation').sum().rename('sum_mm');
    } else {
      // ERA5-LAND daily total_precipitation_sum in meters/day -> convert to mm/day then sum
      sumMmImg = col.select('total_precipitation_sum').sum().multiply(1000).rename('sum_mm');
    }

    // Pixel count and mean precipitation over region
    const reducers = ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true });
    const stats = await getInfo(sumMmImg.reduceRegion({
      reducer: reducers,
      geometry: centralValley,
      scale: scaleMeters,
      maxPixels: 1e9
    }));

    const meanMm = stats ? stats.sum_mm_mean : null;
    const pixCount = stats ? stats.sum_mm_count : 0;

    if (!pixCount || pixCount === 0) {
      console.log(`Dataset: ${dataset}, Images: ${nImages}`);
      console.log('Valid pixels: 0');
      console.log('C2');
      return;
    }

    if (meanMm === null || meanMm === undefined || !isFinite(meanMm) || meanMm < 0) {
      console.log(`Dataset: ${dataset}, Images: ${nImages}`);
      console.log(`Mean(mm): ${meanMm}`);
      console.log('C3');
      return;
    }

    const meanInches = meanMm / 25.4;

    // Area fraction above threshold
    const fracDict = await getInfo(sumMmImg.gte(thresholdMm).rename('gt')
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: centralValley,
        scale: scaleMeters,
        maxPixels: 1e9
      }));
    const frac = fracDict ? fracDict.gt : null;
    const fracPct = (frac !== null && frac !== undefined && isFinite(frac)) ? (frac * 100.0) : null;

    // 4. Output concise evidence (<=20 lines)
    console.log(`Dataset: ${dataset}, Images: ${nImages} (${start} to ${end})`);
    console.log(`Valid pixels: ${pixCount}`);
    console.log(`Area-mean total: ${meanMm.toFixed(1)} mm (${meanInches.toFixed(2)} in)`);
    if (fracPct !== null) {
      console.log(`Area ≥ ${thresholdInches} in: ${fracPct.toFixed(1)}%`);
    }

    // 5. Decision
    if (meanInches >= thresholdInches) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).slice(0, 200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
